from __future__ import annotations
STYLE='''<style id="predibeacon-home-v2-style">.hero-v2{display:grid;grid-template-columns:minmax(0,.9fr) minmax(430px,1.1fr);gap:2rem;align-items:center;padding:3.2rem 0 2rem}.hero-v2 h1{font-size:clamp(2.8rem,6vw,5rem);line-height:.98;margin:.5rem 0 1.2rem}.hero-v2 h1 em{font-style:normal;color:var(--accent)}.hero-copy{color:var(--muted);font-size:1.08rem;line-height:1.65}.trust-row,.quick-filters{display:flex;gap:.55rem;flex-wrap:wrap;margin-top:1rem}.trust-pill,.quick-filter{border:1px solid var(--line);border-radius:999px;padding:.55rem .8rem;font-size:.8rem;font-weight:800}.venue-hub{display:grid;grid-template-columns:1fr .65fr 1fr;gap:.8rem;border:1px solid var(--line);border-radius:20px;padding:1rem;background:linear-gradient(135deg,rgba(139,233,199,.04),rgba(31,94,255,.04))}.venue-card{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:16px;padding:1.15rem;text-decoration:none;background:rgba(17,24,39,.72)}.venue-card:hover{border-color:var(--accent)}.venue-name{font-size:1.25rem;font-weight:900}.venue-count{font-size:2rem;font-weight:900;margin:.7rem 0}.venue-sub{color:var(--muted);font-size:.82rem}.venue-cta{margin-top:1.2rem;font-weight:900;color:var(--accent)}.poly .venue-cta{color:#6ea1ff}.beacon-core{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.beacon-icon{font-size:3.2rem}.beacon-core small{color:var(--muted);margin-top:.4rem}.change-strip{display:flex;gap:.6rem;overflow:auto;border:1px solid var(--line);border-radius:16px;padding:.7rem;margin-bottom:2rem}.change-title{min-width:145px;padding:.65rem;font-weight:900}.change-title small{display:block;color:var(--muted);font-weight:500}.change-item{min-width:190px;border-left:1px solid var(--line);padding:.65rem;font-size:.84rem}.quick-filter{background:transparent;color:var(--text);font:inherit;min-height:44px}.quick-filter[aria-pressed=true]{border-color:var(--accent);color:var(--accent)}.freshness{display:none}.controls label:has(#venue){display:none}.controls{grid-template-columns:1fr}.discovery-explainer{display:none}@media(max-width:900px){.hero-v2{grid-template-columns:1fr}.venue-hub{grid-template-columns:1fr 1fr}.beacon-core{grid-column:1/-1;grid-row:1}}@media(max-width:560px){.venue-hub{grid-template-columns:1fr}.beacon-core{grid-column:auto}.hero-v2 h1{font-size:2.7rem}}</style>'''
SCRIPT=r'''<script id="predibeacon-home-v2-script">(()=>{const hero=document.querySelector('.hero');if(!hero)return;hero.className='hero-v2 wrap';hero.innerHTML=`<div><div class="eyebrow">INTELIGÊNCIA DE MERCADO EM TEMPO REAL</div><h1>Descubra o que está movimentando os <em>mercados de previsão.</em></h1><p class="hero-copy">Kalshi + Polymarket, priorizados, comparados e explicados em um só lugar.</p><div class="trust-row"><span class="trust-pill">✓ Independente</span><span class="trust-pill">✓ Transparente</span><span class="trust-pill">◎ Focado no que importa</span></div></div><div class="venue-hub"><a class="venue-card" href="#markets" data-venue-link="kalshi"><span class="venue-name">Kalshi</span><span class="venue-count" id="v2-k-count">—</span><span class="venue-sub">mercados monitorados</span><span class="venue-cta">Explorar Kalshi →</span></a><div class="beacon-core"><div class="beacon-icon">♜</div><strong>PREDIBEACON</strong><small>Nós analisamos.<br>Você decide.</small></div><a class="venue-card poly" href="#markets" data-venue-link="polymarket"><span class="venue-name">Polymarket</span><span class="venue-count" id="v2-p-count">—</span><span class="venue-sub">mercados monitorados</span><span class="venue-cta">Explorar Polymarket →</span></a></div>`;const markets=document.querySelector('#markets'),controls=markets?.querySelector('.controls');if(controls){const q=document.createElement('div');q.className='quick-filters';q.innerHTML='<button class="quick-filter" aria-pressed="true" data-q="trending">Para você</button><button class="quick-filter" aria-pressed="false" data-q="movers">Em movimento</button><button class="quick-filter" aria-pressed="false" data-q="volume">Mais ativos</button>';controls.insertAdjacentElement('beforebegin',q)}const venue=document.querySelector('#venue'),sort=document.querySelector('#sort');document.querySelectorAll('[data-venue-link]').forEach(a=>a.addEventListener('click',()=>{venue.value=a.dataset.venueLink;venue.dispatchEvent(new Event('change',{bubbles:true}))}));document.querySelectorAll('.quick-filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.quick-filter').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));sort.value=b.dataset.q;sort.dispatchEvent(new Event('change',{bubbles:true}))}));fetch('/api/v1/status').then(r=>r.json()).then(d=>{document.querySelector('#v2-k-count').textContent=d.venue_market_counts?.kalshi||'—';document.querySelector('#v2-p-count').textContent=d.venue_market_counts?.polymarket||'—'}).catch(()=>{});const strip=document.createElement('div');strip.className='change-strip wrap';strip.innerHTML='<div class="change-title">⚡ O que está mudando<small>Dados atuais</small></div><div class="change-item" id="v2-c1">Carregando movimentos…</div><div class="change-item" id="v2-c2">Carregando atividade…</div><div class="change-item" id="v2-c3">Verificando divergências…</div>';hero.insertAdjacentElement('afterend',strip);Promise.all([fetch('/api/v1/markets?sort=movers&limit=1').then(r=>r.json()),fetch('/api/v1/markets?sort=volume&limit=1').then(r=>r.json()),fetch('/api/v1/compare/pairs?limit=12&candidate_limit=24').then(r=>r.json())]).then(([m,v,p])=>{document.querySelector('#v2-c1').textContent=m[0]?`${m[0].title} · ${m[0].probability_change==null?'movimento indisponível':(m[0].probability_change>=0?'↑ ':'↓ ')+Math.abs(m[0].probability_change*100).toFixed(1)+' pts'}`:'Sem movimento relevante';document.querySelector('#v2-c2').textContent=v[0]?`Mais ativo: ${v[0].title}`:'Atividade indisponível';const x=(p.pairs||[]).filter(x=>x.verification?.equivalent_contracts&&x.left.probability!=null&&x.right.probability!=null).sort((a,b)=>Math.abs(b.left.probability-b.right.probability)-Math.abs(a.left.probability-a.right.probability))[0];document.querySelector('#v2-c3').textContent=x?`Maior divergência verificada: ${(Math.abs(x.left.probability-x.right.probability)*100).toFixed(1)} pts`:'Nenhuma divergência verificada agora'}).catch(()=>{})})();</script>'''
def enhance_home_v2(html:str)->str:
    if 'id="predibeacon-home-v2-script"' in html:return html
    out=html.replace('</head>',STYLE+'</head>',1)
    return out.replace('</body>',SCRIPT+'</body>',1)
